mapper.codeEditorJavascript:
const root=typeof input.body==='string'?JSON.parse(input.body):input.body;
const arr=x=>x==null?[]:Array.isArray(x)?x:[x];
const scalar=x=>{x=arr(x)[0];return typeof x==='object'?x?._value:x;};
const rows=arr(root.multistatus?.response).map(r=>{
 const ps=arr(r.propstat).find(p=>/ 200 /.test(scalar(p.status)||''));
 if(!ps)throw Error('Inventory property failure');
 const p=arr(ps.prop)[0],v=scalar(p['address-data']);
 if(typeof v!=='string')throw Error('Missing vCard');
 const lines=v.replace(/\r\n[ \t]/g,'').split(/\r?\n/);
 const values=k=>lines.filter(l=>l.split(':')[0].split(';')[0].split('.').at(-1).toUpperCase()===k).map(l=>l.slice(l.indexOf(':')+1));
 const uid=values('UID'); if(uid.length!==1)throw Error('Ambiguous UID');
 return {id:uid[0],href:scalar(r.href),etag:scalar(p.getetag),name:values('FN')[0]||'',emails:values('EMAIL'),phones:values('TEL')};
}); if(new Set(rows.map(r=>r.id)).size!==rows.length)throw Error('Duplicate UID');
if(rows.length!==Number(input.expected))throw Error('Incomplete batch');return {offset:input.offset,count:rows.length,compressed:require('node:zlib').gzipSync(JSON.stringify(rows)).toString('base64')};
